List<String> sortAsciiRowsByAlignment(List<String> rows) {
  if (rows.isEmpty) return [];

  int computeKey(String row, String baseRow) {
    int diff = 0;
    for (int i = 0; i < min(row.length, baseRow.length); ++i) {
      final c1 = row.codeUnitAt(i);
      final c2 = baseRow.codeUnitAt(i);
      diff += (c1 - c2).abs();
    }
    return diff;
  }

  List<int> keyIndices = List.generate(rows.length, (idx) => idx);

  // Sort using the sum of absolute differences with the first row
  void quickSort(int low, int high) {
    if (low >= high) return;

    var pivotIndex = low + ((high - low) ~/ 2);
    int pivotVal = computeKey(rows[pivotIndex], rows[0]);

    List<int> leftSide = List<int>.generate(high - low, (index) =>
        computeKey(rows[index + low], rows[0]));
    List<int> rightSide = List<int>.generate(high - low, (index) =>
        computeKey(rows[index + low], rows[0]));

    int l = low;
    int r = high;

    while (l <= r) {
      while (computeKey(rows[l], rows[0]) < pivotVal && l <= r) {
        ++l;
      }
      while (computeKey(rows[r], rows[0]) > pivotVal && l <= r) {
        --r;
      }
      if (l <= r) {
        int temp = keyIndices[l];
        keyIndices[l] = keyIndices[r];
        keyIndices[r] = temp;
        ++l;
        --r;
      }
    }

    quickSort(low, r);
    quickSort(l, high);
  }

  quickSort(1, rows.length - 1);

  List<String> sortedRows = List.from(rows)..sort((a, b) {
    int aKey = computeKey(a, rows[keyIndices[0]]);
    int bKey = computeKey(b, rows[keyIndices[0]]);
    return aKey.compareTo(bKey);
  });
  return sortedRows;
}

