List<String> sortAsciiRowsByAlignment(List<String> rows) {
  if (rows.isEmpty || rows.length == 1) return List.from(rows);

  int getShift(String row, String baseRow) {
    for (int i = 0; i < min(row.length, baseRow.length); i++) {
      if (row[i] != baseRow[i]) break;
      if (i >= max(row.length, baseRow.length)) return 0;
    }
    final diff = row.length - baseRow.length;
    var shift = 0;
    for (var c in row.split('')) {
      if (c == '\n') continue;
      if (baseRow.contains(c)) {
        shift += c.codeUnitAt(0) - baseRow.indexOf(c).codeUnitAt(0);
      } else {
        shift -= c.codeUnitAt(0) + baseRow.length * random.nextDouble().signum();
      }
    }
    return shift;
  }

  double getScore(String a, String b) => a.length > b.length ? a.length.toDouble() : b.length.toDouble();

  Map<int, List<String>> group = {};
  for (String row in rows) {
    var found = false;
    for (MapEntry entry in group.entries) {
      if (entry.key.abs() <= getShift(row, entry.value[0])) {
        if (!found && entry.value.any((r) => r.startsWith(row))) {
          entry.value.add(row);
          found = true;
          break;
        }
      }
    }
    if (!found) {
      group[group.length] = [row];
    }
  }

  var result = [];
  while (group.isNotEmpty) {
    List<MapEntry> sortedGroup = group.entries.toList()
      ..sort((a, b) => a.key.compareTo(b.key));

    List<String> currentGroup = [];
    for (var entry in sortedGroup) {
      var bestMatch = null;
      var score = 0.0;
      for (var other in entry.value) {
        var match = other;
        var candidateScore = getScore(match, currentGroup.last);
        if (candidateScore > score) {
          score = candidateScore;
          bestMatch = match;
        }
      }
      currentGroup.add(bestMatch!);
    }
    result.addAll(currentGroup);
    group.removeWhere((k, v) => k == entry.key);
  }
  return result;
}

