  int minAlignCol = 0;
  for (int i = 0, j = 0; i < rows.length; ++i) {
    while (j < rowWidths[i]) {
      String s = rows[i].substring(j++);
      if (!s.trim().isEmpty) {
        minAlignCol = max(minAlignCol, j - 1);
        break;
      }
    }
  }

  void alignRow(StringBuilder sb, String row, int col) {
    int start = col >= row.length ? 0 : col;
    int end = row.length;
    int pad = start > 0 ? start - 1 : 0;
    int count = 0;
    while (count++ < pad) sb.write(' ');
    sb.write(row.substring(start));
  }

  List<Iterable> alignedRows =
      rows.map((r) => r.split('\n')).expand((e) => e).toList();

  int left = 0;
  List<String> result = [];

  while (left < alignedRows.length) {
    int firstNonEmpty = left;
    while (
        firstNonEmpty < alignedRows.length &&
        alignedRows[firstNonEmpty]!.trim().isNotEmpty)
      ++firstNonEmpty;
    if (firstNonEmpty <= left) continue;

    String firstLine = alignedRows[left];
    int col = 0;
    for (; col < firstLine.length && !firstLine[col].isWhitespace(); ++col);

    List<String> currentLines = [firstLine];

    for (int i = left + 1; i < firstNonEmpty;) {
      String line = alignedRows[i++];
      int len = line.length;
      int lastNonSpace = 0;
      for (int j = len - 1; j >= 0 && !line[j].isWhitespace(); --j) {
        lastNonSpace = j;
      }
      int indent = lastNonSpace + 1;
      int newIndent = 0;
      for (; newIndent < indent && newIndent < col && !line[newIndent].isWhitespace();
          ++newIndent)
        ;
      if (newIndent != indent ||
          (newIndent < col && line[lastNonSpace] is! '\t')) {
        col = newIndent;
        currentLines.clear();
      } else {
        currentLines.add(line);
      }
    }

    StringBuilder sb = StringBuffer();
    alignRow(sb, firstLine, col);
    for (String l in currentLines.sublist(1)) {
      alignRow(sb, l, col);
    }
    result.add(sb.toString());

    left = firstNonEmpty;
  }

  return result;
}

