List<String> sortAsciiRowsByAlignment(List<String> rows) {
  if (rows.length < 2) return List.from(rows);

  final int compare = (String a, String b) => 
    (a[0] != b[0]) ? a.codeUnitAt(0).compareTo(b.codeUnitAt(0)) : 
      a.length.compareTo(b.length); 

  for (int i = 1; i < rows.length; ++i) {
    String key = rows[i];
    int j = i - 1;

    while (j >= 0 && compare(key, rows[j]) <= 0) {
      rows[j + 1] = rows[j];
      --j;
