    rows[j + 1] = key;
  }

  return rows;
}

List<String> sortAsciiRowsByAlignment(List<String> rows) {
  if (rows.length < 2) return List.from(rows);

  int compareRow(String a, String b) {
    final lenA = a.length;
    final lenB = b.length;

    for (int i = 0; i < min(lenA, lenB); ++i) {
      if (a[i] != b[i]) {
        // Return based on the first differing character
        return a[i].codeUnitAt(0) - b[i].codeUnitAt(0);
      }
    }

    // If one is prefix of other:
    return lenA.compareTo(lenB);
  }

  return rows..sort(compareRow);
}

