      if (result[i][result[j].length] != '\t') break;
      j++;
    }

    if (j < result.length) {
      final tempRow = result.removeAt(j);
      result.insert(i, tempRow);

      for (int k = i + 1; k < result.length - 1; k++) {
        int l = k + 1;
        while (l < result.length && result[k].length >= result[l].length) {
          if (result[k][result[l].length] != '\t') break;
          l++;
        }

        if (l < result.length) {
          final swapped = result.removeAt(l);
          result.insert(k, swapped);

          for (int m = k + 1; m < result.length; m++) {
            int n = m + 1;
            while (n < result.length && result[m].length >= result[n].length) {
              if (result[m][result[n].length] != '\t') break;
              n++;
            }

            if (n < result.length) {
              final moved = result.removeAt(n);
              result.insert(m, moved);
            }
          }
        }
      }
    }
  }

  return result;
}

