int countWifiBinPartitions(List<int> signals, int maxTolerance) {
  if (signals.isEmpty || maxTolerance == 0) return 1;

  final n = signals.length;
  List<List<int>> dp = List.generate(n + 1, (_) => List.filled(32768, -1));
  List<int> prevSignal = <int>[...signals];

  void update(int i, int j, int tolerance) {
    for (var k in [...prevSignal.sublist(i).takeWhile((v) => v != null)]) {
      var newSignal = [...k <= j ? [j] : [] ... prevSignal.sublist(j)];
      if (newSignal.last >= k && newSignal.last - k > tolerance) break;
      if (dp[j].contains(newSignal)) continue;

      var last = newSignal.last;
      while (last < k) {
        newSignal.add(last);
        last++;
      }
      var nextJ = newSignal.indexWhere((s) => s == null ?? false);
      if (nextJ == -1) continue; // no more elements to add
      if (newSignal.length > n) continue;
      if (!dp[nextJ].contains(newSignal)) dp[nextJ] = newSignal.toList();
    }

    for (var k in [...prevSignal.sublist(i).skipWhile((v) => v != null)]) {
      var newSignal = [...prevSignal.sublist(i).takeWhile((v) => v != null), k];
      if (newSignal.isNotEmpty && newSignal.last >= k && newSignal.last - k > tolerance) continue;
      if (dp[k].length > n) continue;
      if (dp[k].isNotEmpty && dp[k][dp[k].length-1] >= k) continue;
      dp[k] = newSignal;
    }
  }

  void backtrack(int i, int j, int len, bool isLeft) {
    if (i >= n) {
      print('Partitioned into $len partitions');
      return;
