    result.add('$min');
  }
  return result;
}

void swapMinutes(List<int> list, int i, int j) {
  int temp = list[i];
  list[i] = list[j];
  list[j] = temp;
}

int partition(List<int> list, int left, int right) {
  int pivot = list[(left + right) ~/ 2];
  int i = left;
  int j = right;

  while (i <= j) {
    while (list[i] < pivot) i++;
    while (list[j] > pivot) j--;

    if (i <= j) {
      swapMinutes(list, i, j);
      i++;
      j--;
    }
  }

  return j;
}

