  int row = -1, col = -1;
  for (int i = 0; i < rows.length && row == -1; i++) {
    final firstNonSpace = rows[i].trimLeft().firstWhereOrNull((c) => c != ' ');
    if (firstNonSpace != null) {
      if (row == -1) {
        row = i;
        col = firstNonSpace.indexInString(rows[row]);
