  bool isRowValid(int r) => r >= 0 && r < rows.length;
  bool isColValid(int c) => c >= 0 && c < rows[r].length;

  while (col >= 0) {
    final direction = rows[row][col];
    if (!dirMap.containsKey(direction)) return false;

    final step = dirMap[direction]!;
    final nextRow = row + step[0];
    final nextCol = col + step[1];

    if (!isRowValid(nextRow)) return false;
    if (!isColValid(nextCol)) return false;

    // Check that the new cell has a valid character
    final nextChar = rows[nextRow][nextCol];
    if (!dirMap.containsKey(nextChar)) return false;

    row = nextRow;
    col = nextCol;
  }

  return true;
}

