int _calculateLevenshteinDistance(String a, String b) {
  final m = a.length;
  final n = b.length;
  var dp = List<List<int>>.generate(m + 1, (_) => List.filled(n + 1, 0));
  for (var i = 0; i <= m; ++i) dp[i][0] = i;
  for (var j = 0; j <= n; ++j) dp[0][j] = j;

  for (var i = 1; i <= m; ++i) {
    for (var j = 1; j <= n; ++j++) {
      int cost = (a.codeUnitAt(i-1) == b.codeUnitAt(j-1)) ? 0 : 1;
      dp[i][j] = min(
          dp[i - 1][j] + 1,
          dp[i][j - 1] + 1,
          dp[i - 1][j - 1] + cost
      );
    }
  }

  return dp[m][n];
}

