    String name = manifest.substring(i, j);
    items.add(name);
    i = j - 1;
  }

  Map<String, int> result = {};
  for (var item in items) {
    int quantity = 1;
    bool isWeighted = false;

    for (int k = 0; k < item.length; ++k) {
