        isWeighted = true;
        continue;
      } else if (item[k] == ')' || item[k] == ',' || item[k] == ']') {
        break;
      } else if (isWeighted && item[k].isDigit()) {
        quantity *= int.parse(item[k]);
      } else if (isWeighted && !item[k].isDigit() && k > 0) {
        return {'error': 2};
      }
    }

    if (!result.containsKey(item)) {
      result[item] = quantity;
    } else {
