      } else if (nums[i]!.toInt() >= 97 && nums[i]!.toInt() <= 122) {
        item += String.fromCharCode(nums[i]!).toLowerCase();
        i++;
        foundId = true;
      } else if (nums[i]!.toInt() == 123 || nums[i]!.toInt() == 125) {
        i++;
        break;
      } else {
        i++;
      }
    }

    if (foundId) {
      int count = 0;
      while (
          i < nums.length && nums[i] != null &&
          (nums[i]!.toInt() == 32 || nums[i]!.toInt() == 96)) {
        i++;
      }

      if (i < nums.length && nums[i] != null) {
        count = nums[i]++;
        result[item] ??= 0;
        result[item] = result[item]! + count;
      }
    }
  }

  return result;
}

