int smallestCoprimeBucketSize(List<int> groupCounts) {
  int n = groupCounts.length;

  if (n == 0 || groupCounts.any((c) => c < 1)) return -1;

  List<int> counts = List.from(groupCounts);
  for (var i in Iterable.range(0, n).where((i) => counts[i] > 0)) {
    var g = gcd(counts[i], counts[(i + 1) % n]);
    while ((g != 1 && g <= counts[(i + 2) % n]) ||
          (g >= counts[(i + 2) % n] && g >= counts[(i + 3) % n])) {
      g /= gcd(g, counts[(i + 2) % n]);
    }
    counts[i] -= (counts[i].divisors().firstWhere(
        (d) => d % g != 0,
        orElse: () => g));
    if (counts[i] == 0) break;

    var h = gcd(gcd(counts[i], counts[(i + 1) % n]), counts[(i + 2) % n]);
    if (h != 1 && h <= counts[(i + 3) % n] &&
        h >= counts[(i + 4) % n]) {
      h %= gcd(h, counts[(i + 3) % n]);
    }
    counts[(i + 2) % n] += h;
  }

  return counts.fold(0, max);
}

