double computeBracketOpponentAverage(String encoded) {
  // Run-length encoded tournament bracket winner seeds.
  // Tournament: 4-team single elimination, fixed bracket:
  //   Semifinal 1: seed 1 vs 4
  //   Semifinal 2: seed 2 vs 3
  //   Final: winner S1 vs winner S2
  // Encoded string: sequence of pairs (seed digit, count digit).
  // Expanded order: winner S1, winner S2, winner Final.
  // Returns average seed of opponents beaten by the champion (double).
  // Invalid input returns 0.0.
  if (encoded.isEmpty || encoded.length % 2 != 0) return 0.0;
  List<int> winners = [];
  for (int i = 0; i < encoded.length; i += 2) {
    int seed, count;
    try {
      seed = int.parse(encoded[i]);
      count = int.parse(encoded[i + 1]);
    } catch (_) {
      return 0.0;
    }
    if (seed < 1 || seed > 4 || count < 1) return 0.0;
    for (int j = 0; j < count; j++) {
      winners.add(seed);
      if (winners.length > 3) return 0.0; // too many matches
    }
  }
  if (winners.length != 3) return 0.0;
  int w1 = winners[0], w2 = winners[1], champion = winners[2];
  // Validate bracket composition
  if ((w1 != 1 && w1 != 4) || (w2 != 2 && w2 != 3) || (champion != w1 && champion != w2)) {
    return 0.0;
  }
  int opponent1, opponent2;
  if (champion == w1) {
    // Champion came from semifinal 1
    opponent1 = (w1 == 1) ? 4 : 1; // opponent in semi
    opponent2 = w2;                // opponent in final
  } else { // champion == w2
    opponent2 = w1;                // final opponent
    opponent1 = (w2 == 2) ? 3 : 2; // semi opponent
  }
  return (opponent1 + opponent2) / 2.0;
}

