    for (int i = left; i < right; i++) {
      if (absValues[i] <= pivot) {
        swap(storeIndex++, i);
      }
    }

    swap(storeIndex, right);
    return storeIndex;
  }

  quickSelect(0, absValues.length - 1, k - 1);
  return absValues[k - 1];
}

