Map<String, int> reconcileShippingManifest(List<List<String>> yard) {
  if (yard.isEmpty) return {};
  int rows = yard.length;
  int cols = yard[0].length;
  List<String> sequence = [];
  for (int d = 0; d < rows + cols - 1; d++) {
    int rStart = d < cols ? 0 : d - cols + 1;
    int cStart = d < cols ? d : cols - 1;
    int r = rStart, c = cStart;
    while (r < rows && c >= 0) {
      if (yard[r][c] != '') {
        sequence.add(yard[r][c]);
      }
      r++;
      c--;
    }
  }
  Map<String, int> firstSeen = {};
  Set<String> seen = {};
  Set<String> duplicates = {};
  for (int i = 0; i < sequence.length; i++) {
    String code = sequence[i];
    if (seen.contains(code)) {
      duplicates.add(code);
    } else {
      seen.add(code);
      firstSeen[code] = i;
    }
  }
  Map<String, int> result = {};
  for (String code in duplicates) {
    result[code] = firstSeen[code]!;
  }
  return result;
}

