String processPlaylistCommands(List<String> commands) {
  final queue = <int>[]; // Queue for playlist
  int pointer = -1;

  void movePointer(int step, bool forward) {
    if (forward) {
      while (step > 0 && pointer + 1 < queue.length) {
        ++pointer;
        --step;
      }
    } else {
      while (step > 0 && pointer >= 0) {
        --pointer;
        --step;
      }
    }
  }

  String result = '';
  for (final command in commands) {
    switch (command) {
      case 'play':
        if (queue.isNotEmpty) {
          result += '|${queue[pointer]}| ';
          pointer++;
        }
        break;
      case 'pause':
        result += 'P';
        break;
      case 'next':
        movePointer(1, true);
        break;
      case 'prev':
        movePointer(1, false);
        break;
      default:
        break;
    }
  }

  return result.trim();
}

