    }
    return parts.join('\n');
  } else {
    List<String> result = [];
    int idx = 0;
    while (idx < n && !commands[idx].startsWith('add ')) ++idx;
    for (int i = idx; i < n; ++i) {
      String line = commands[i];
      if (line.isEmpty) continue;
      if (line.endsWith(':')) {
        result.add(line);
      } else {
        result.add('$line:');
      }
    }
    return result.join('\n');
  }
}

