      result.add(value);
    } else if (cmd == 'POP') {
      if (result.isNotEmpty) {
        result.removeLast();
      }
    } else if (cmd == 'ADD') {
      int a = result.removeAt(result.length - 1);
      int b = result.removeAt(result.length - 1);
      result.add(a + b);
    } else if (cmd == 'SUB') {
      int a = result.removeAt(result.length - 2);
      int b = result.removeAt(result.length - 1);
      result.add(b - a);
    } else if (cmd == 'MUL') {
      int a = result.removeAt(result.length - 1);
      int b = result.removeAt(result.length - 1);
      result.add(a * b);
    } else if (cmd == 'DIV') {
      int a = result.removeAt(result.length - 2);
      int b = result.removeAt(result.length - 1);
      if (b != 0) {
        result.add(b ~/ a);
      } else {
        throw Exception('Division by zero');
      }
    } else if (cmd == 'MOD') {
      int a = result.removeAt(result.length - 2);
      int b = result.removeAt(result.length - 1);
      if (b != 0) {
        result.add(b % a);
      } else {
        throw Exception('Modulo by zero');
      }
    } else if (cmd == 'NEG') {
      int a = result.removeLast();
      result.add(-a);
    } else if (cmd == 'ABS') {
      int a = result.removeLast();
      result.add(a.abs());
    } else if (cmd == 'MIN') {
      if (result.isEmpty || result.length < 2) {
        throw Exception("Not enough elements for MIN");
      }
      int minVal = result[0];
      for (int i = 1; i < result.length; ++i) {
        if (result[i] < minVal) {
          minVal = result[i];
        }
      }
      result.add(minVal);
    } else if (cmd == 'MAX') {
      if (result.isEmpty || result.length < 2) {
        throw Exception("Not enough elements for MAX");
      }
      int maxVal = result[0];
      for (int i = 1; i < result.length; ++i) {
        if (result[i] > maxVal) {
          maxVal = result[i];
        }
      }
      result.add(maxVal);
    } else if (cmd == 'SIZE') {
      result.add(result.length);
    } else if (cmd == 'JOIN') {
      if (result.isEmpty || result.length < 2) {
        throw Exception("Not enough elements for JOIN");
      }
      String joined = '';
      for (int i = 0; i < result.length; ++i) {
        joined += result[i].toString();
      }
      result.add(int.tryParse(joined) ?? throw Exception("Invalid join"));
    } else {
      throw Exception("Unknown command: $cmd");
    }
  }
  return result.join(',');
}

