      break;
    }
  }

  if (minCycleLen == int.maxValue) return [];

  List<int> bands = [];
  for (int k=0; k < n; k++) {
    int bandIndex = k % minCycleLen;
    bands.add(bandIndex);
  }
  return bands;
}

