  for (int i = 0; i < n; i++) {
    List<int> bandPattern = [];
    Set<int> seenValues = {};

    for (int j = i + 1; j <= n; j++) {
      int value = readings[j % n];
      if (seenValues.contains(value)) break;
      seenValues.add(value);
      bandPattern.add(value);

      if (bandPattern.length > maxBandLength) {
        maxBandLength = bandPattern.length;
      }
    }
  }

  List<int> result = [];

  if (maxBandLength == 0) return result;

  while (result.length < n && maxBandLength != 0) {
    int count = 0;
    int currentVal = readings[0];
    for (int val in readings) {
      if (val == currentVal) count++;
      else break;
    }

    if (count >= maxBandLength) {
      result.addAll(Iterable.generate(maxBandLength, (_) => currentVal));
