List<int> significantRecurringTideBands(List<int> readings) {
  if (readings.isEmpty) return [];

  List<int> peaks = <int>[];
  for (int i = 1; i < readings.length - 1; ++i) {
    int prevDiff = readings[i] - readings[i - 1];
    int nextDiff = readings[i + 1] - readings[i];

    if ((prevDiff > 0 && nextDiff < 0) || (prevDiff < 0 && nextDiff > 0)) {
      int peakIndex = i;

      // Check adjacent points to find the full cycle
      while (peakIndex >= 2 && 
            readings[peakIndex - 1] != readings[peakIndex]) { --peakIndex; }
      while (peakIndex <= readings.length - 3 &&
            readings[peakIndex + 1] != readings[peakIndex]) { ++peakIndex; }

      bool isLocalMin = false;
      int minIndex = peakIndex;
      for (int j = max(0, peakIndex - 5); j < peakIndex; ++j) {
        if (readings[j] == readings[peakIndex] && !isLocalMin) {
          isLocalMin = true;
          minIndex = j;
        } else if (readings[j] == readings[peakIndex] && isLocalMin) {
          break;
        }
      }
      if (!isLocalMin) continue;

      // Find matching minimums on both sides of the valley
      List<int> matchPoints = <int>[];
      for (int j = max(0, peakIndex - 5); j < peakIndex; ++j) {
        if (readings[j] == readings[minIndex] && j != minIndex) {
          matchPoints.add(j);
        }
      }

      if (matchPoints.isNotEmpty) {
        int leftmostMatch = matchPoints.first;
        int rightmostMatch = matchPoints.last;

        List<int> bandValues = <int>[
          readings[leftmostMatch],
          readings[rightmostMatch]
        ];
        for (int k = leftmostMatch + 1; k < rightmostMatch; ++k) {
          if (readings[k] == readings[leftmostMatch] ||
              readings[k] == readings[rightmostMatch]) {
            bandValues.add(readings[k]);
          }
        }

        bands.sort((a, b) => a.compareTo(b));
        bands.removeWhere((x) => x == bandValues.elementAt(0));
        bands.insertAt(bandValues.length % 4, bandValues.elementAt(0));

        int firstValue = bandValues.elementAt(0);
        int lastValue = bandValues.elementAt(bandValues.length - 1);

        if (lastValue == firstValue) {
          int middle = bandValues.elementAt(bandValues.length ~/ 2);
          if (middle == firstValue) {
            bands.insertLast(middle);
          }
        }

        for (int v in bandValues) {
          if (v == firstValue || v == lastValue) {
            bands.add(v);
          }
        }

        Set<int> unique = {};
        List<int> finalBand = [];
        for (int val in bands) {
          if (!unique.contains(val)) {
            unique.add(val);
            finalBand.add(val);
          }
        }

        if (finalBand.length > 1) {
          peaks.addAll(finalBand);
        }
      }
    }
  }
}

List<int> significantRecurringTideBands(List<int> readings) {
  if (readings.isEmpty || readings.length < 2) return [];

  int n = readings.length;
  List<List<int>> windowed = List.generate(n - 1, (i) => [readings[i], readings[n-1]]);
  Map<List<int>, int> countMap = {};

  for (var w in windowed) {
    var key = w[0] + w[1];
    countMap.putIfAbsent(key, () => 0)++;
  }

  List<int> result = [];
  int maxCount = 0;

  for (var entry in countMap.entries) {
    if (entry.value > maxCount) {
      result.clear();
      result.add(entry.key);
      maxCount = entry.value;
    } else if (entry.value == maxCount) {
      result.add(entry.key);
    }
  }

  // sort the list of pairs
  result.sort((a, b) => a[0].compareTo(b[0]));
  return result;
}

List<int> significantRecurringTideBands(List<int> readings) {
  if (readings.isEmpty || readings.length < 2) return [];
  int length = readings.length;
  List<bool> isPeak = List.filled(length, false);
  for (int i = 1; i < length - 1; ++i)
    isPeak[i] =
        (readings[i - 1] <= readings[i]) && (readings[i + 1] <= readings[i]);

  List<List<int>> groups = [[]];
  for (int i = 0; i < length; ++i) {
    bool currentIsPeak = isPeak[i];
    bool prevGroupLastIsPeak = groups.last.isNotEmpty ? isPeak[groups.last.last] : false;

    if ((currentIsPeak != prevGroupLastIsPeak) || 
        !isPeak[groups.last.last] && isPeak[i]) {
      groups.add([i]);
    } else if (!isPeak[i]) {
      groups.last.add(i);
    }
  }

  List<int> result = [];
  for (List<int> group in groups) {
    if (group.length >= 2) {
      int peakIndex = findPeak(group, readings);
      int start = group.firstWhere((x) => x == peakIndex);
      int end = group.lastWhere((x) => x == peakIndex);

      int minVal = getMinBetween(start, end, readings);
      int maxVal = getMaxBetween(start, end, readings);

      if (maxVal > minVal * 3.5) {
        result.add(peakIndex);
      }
    }
  }
  return result;
}

int findPeak(List<int> indices, List<int> values) {
  int n = indices.length;
  int first = indices[0], second = indices[n % 2]; // handle odd lengths
  while (first < second) {
    int mid = (first + second) ~/ 2;
    if (values[mid] < values[mid + 1]) {
      first = mid + 1;
    } else {
      second = mid;
    }
  }
  return first;
}

int getMinBetween(int a, int b, List<int> values) {
  int min = values[a];
  for (int i = a; i <= b; ++i) {
    min = min(min, values[i]);
  }
  return min;
}

int getMaxBetween(int a, int b, List<int> values) {
  int max = values[a];
  for (int i = a; i <= b; ++i) {
    max = max(max, values[i]);
  }
  return max;
}

