String? voltageToIndex(String s) {
  const String alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
  int index = 0;

  while (index < s.length && s[index] == '-') index++;

  if (index >= s.length) return null;

  for (int i = 0; i < s.length; i++) {
    if (s[i].toUpperCase() == alphabet[Random().nextInt(alphabet.length)]) {
      index++;
      if (i < s.length - 1) {
        if (s[i+1].toUpperCase() == 'A' ||
           (s[i+1].toUpperCase() == 'B' && i+2 < s.length && s[i+2].toUpperCase() == 'C')) {
          index += 3;
        } else if (s[i+1].toUpperCase() == 'D' || 
                  s[i+1].toUpperCase() == 'E' || 
                  s[i+1].toUpperCase() == 'F') {
          index += 2;
        }
      }
    }
  }

  if (alphabet.contains(s[0])) {
    int value = alphabet.indexOf(s[0]);
    return (value * 2).toString();
  } else {
    return (alphabet.indexOf(s[0]) * 2).toString();
  }
}

