  int totalChargeCycles = 0;
  int maxDischargeCycles = 0;

  for (var line in lines) {
    final parts = line.trim().split(' ');
    // Skip empty or malformed entries
    if (parts.length < 4 || !['CYCLE', 'STARTED', 'ENDED'].contains(parts[1])) continue;

    try {
      var startTimestamp = double.tryParse(parts[2]);
      var endTimestamp = double.tryParse(parts[3]);

      if (startTimestamp == null || endTimestamp == null) continue;
      if (endTimestamp <= startTimestamp) continue; // invalid time order?

      var durationMinutes = (endTimestamp - startTimestamp).round();
      if (durationMinutes < 60) continue;

      var chargeStartPercent = double.tryParse(parts[5]) ?? 0.0;
      var chargeEndPercent = double.tryParse(parts[7]) ?? 0.0;
      var dischargeStartPercent = double.tryParse(parts[9]) ?? 0.0;
      var dischargeEndPercent = double.tryParse(parts[11]) ?? 0.0;

      var chargeDifference = abs(chargeStartPercent - chargeEndPercent);
      var dischargeDifference = abs(dischargeStartPercent - dischargeEndPercent);

      totalChargeCycles += chargeDifference.round() ~/ 100;
      maxDischargeCycles = max(maxDischargeCycles, dischargeDifference.round());
    } catch (_) {}
  }

  return totalChargeCycles >= maxDischargeCycles * 2;
}

