      path.add(i);
    } else {
      int nextValidStep;

      do {
        nextValidStep = (path[path.length-1] + 1) % (rows*cols)+1;

        int nextRow = (nextValidStep - 1) % rows;
        int nextCol = (nextValidStep ~/ rows) % cols;

