// Helper function to compute the minimum number of edits
// needed to convert a string s into another string t.
// Returns null if either s or t is empty and not equal.
int? editDistance(String s, String t) {
  // If one of them is empty, handle accordingly
  if (s.isEmpty && t.isNotEmpty) {
    return t.length;
  } else if (t.isEmpty && s.isNotEmpty) {
    return s.length;
  }

  final rows = s.length;
  final cols = t.length;

  List<List<int>> dp = List.generate(rows + 1, (_) => List.filled(cols + 1, 0));

  for (int row = 1; row < rows + 1; row++) {
    dp[row][0] = row;
  }
  for (int col = 1; col < cols + 1; col++) {
    dp[0][col] = col;
  }

  for (int row = 1; row < rows + 1; row++) {
    for (int col = 1; col < cols + 1; col++) {
      if (s[row - 1] == t[col - 1]) {
        dp[row][col] = dp[row - 1][col - 1];
      } else {
        dp[row][col] = min(dp[row - 1][col], dp[row][col - 1], dp[row - 1][col - 1]);
      }
    }
  }
  return dp[rows][cols];
}

