  final aTimes = [0] + lineA.map((x) => x).toList();
  final bTimes = [0] + lineB.map((x) => x).toList();

  final dp = List.generate(aTimes.length * bTimes.length, (_) => -1);
  for (var i = 0; i < aTimes.length; ++i)
    dp[i * bTimes.length] = 0;

  void dfs(int ai, int bi) {
    var bestTime = -1;
    if (ai >= aTimes.length || bi >= bTimes.length) return;

    for (int t = minTransfer; t <= maxTransfer && t <= bTimes[bi]; ++t) {
      final time = aTimes[ai] + t;
      if (time > bTimes[bi]) continue;

      if (dp[ai + bi] == -1 || dp[ai + bi] < time) {
        dp[ai + bi] = time;
        dfs(ai, bi + 1); // Next bus from B
        dfs(ai + 1, bi); // Next bus from A
      }
    }

    for (int nextAi = ai + 1; nextAi < aTimes.length; ++nextAi) {
      final waitA = aTimes[nextAi] - aTimes[ai];
      final newBi = bi;
      final newAi = nextAi;
      final time = waitA + (newBi >= bTimes.length ? 0 : bTimes[newBi]);

      if (time > maxTransfer) break;
      if (dp[newAi + newBi] == -1 || dp[newAi + newBi] < time) {
        dp[newAi + newBi] = time;
        dfs(newAi, newBi);
      }
    }
  }

  dfs(0, 0);

  final result = List<int>.filled(dp.length, -1);
  for (var i = 0; i < dp.length; ++i) {
    if (dp[i] != -1) result[i % aTimes.length] = dp[i];
  }

  return result.toList().whereType<num>().map((n) => n.toInt()).toList();
}

