    // Generate all possible moves a knight can make from this position
    List<String> nextMoves = [
      "${x + 2},${y + 1}",
      "${x + 1},${y + 2}",
      "${x - 1},${y + 2}",
      "${x - 2},${y + 1}",
      "${x - 2},${y - 1}",
      "${x - 1},${y - 2}",
      "${x + 1},${y - 2}",
      "${x + 2},${y - 1}"
