    int pos = queue.removeFirst();
    int r = pos ~/ m;
    int c = pos % m;

    if (r == n-1 && c == m-1) break;

    for (List<int> move in [[2, 1], [1, 2], [-1, 2], [-2, 1],
                           [-2, -1], [-1, -2], [1, -2], [2, -1]]) {
      int nr = r + move[0];
      int nc = c + move[1];

      if (isSafe(nr, nc)) {
        int nextPos = nr * m + nc;
