        break;
      case 'K':
        ++result['diamonds']!;
        break;
      case 'Q':
        ++result['clubs']!;
        break;
      default:
        if ('2' <= rankChar && rankChar <= '9') {
          int value = int.parse(rankChar.toString());
          if (value >= 7) { // only count A-K-Q
            if (value == 8 || value == 9) {
              ++result['spades']!; 
            }
          }
        }
    }
  }

  return result;
}

