    if (!notation[i].isDigit()) continue;
    try { 
      var n = int.parse(notation[i]);
      if (n >= 2 && n <= 9 || n == 10) {
        numbers.add(n);
      }
    } catch (_) {}
  }

  final Map<String, int> result = {};
  const suits = {'S', 'H', 'D', 'C'};
  for (final suit in suits) {
    result[suit] = 0;
  }

  for (var i = 0; i < numbers.length; ++i) {
    final c = notation[numbers[i]];
    if (c is! String || c.isEmpty) continue;

    bool found = false;
    for (final suit in suits) {
      if (suit != c) continue;
      result[c]++;
      found = true;
      break;
    }
    if (!found) {
      result['?'] ??= 0;
      result['?']++;
    }
  }

  return result;
}

