Map<String, int> analyzeMazeSegments(List<List<int>> mazeGrid) {
  final segments = <String, List<Set<int>>> {};
  final visited = Set<Set<int>>();

  void visit(int r, int c) {
    if (r >= 0 && c >= 0 && r < mazeGrid.length && c < mazeGrid[0].length &&
        !visited.contains({r, c}) && mazeGrid[r][c] != -1) {
      final key = '$r,$c';
      final set = {r, c};

      for (final d in [3, 4, 5, 6]) {
        final nr = r + [-1, 0, 1, 0][d % 4];
        final nc = c + [0, 1, 0, -1][d % 4];

        if (nr >= 0 && nc >= 0 && nr < mazeGrid.length && nc < mazeGrid[0].length) {
          if (!visited.contains({nr, nc})) {
            if (mazeGrid[nr][nc] == mazeGrid[r][c]) {
              final newKey = "$nr,$nc";

              // If this neighbor has not been added before
              if (!segments.containsKey(newKey)) {
                segments[newKey] = [];

                final prev = segments[key];
                if (prev!.contains(set)) {
                  segments.remove(key);
                } else {
                  prev.add(set); 
                }
              } else {
                final newSeg = segments[newKey]!;

                if (!newSeg.contains(set)) {
                  newSeg.add(set);
                }

                // Check if current segment is part of another segment
                final prevSegs = segments[key]!; 
                if (prevSegs.contains(set)) {
                  segments.remove(key);
                }
              }
            }

            final nextKey = "$nr,$nc";
            if (!segments.containsKey(nextKey)) {
              segments[nextKey] = [];
            }

            if (!segments[nextKey]!.contains(set)) {
              segments[nextKey]!.add(set);
            }

            visit(nr, nc);
          }

          break;
        }
      }
    }
  }

  for (int i = 0; i < mazeGrid.length; i++) {
    for (int j = 0; j < mazeGrid[i].length; j++) {
      if (mazeGrid[i][j] != -1 && !visited.contains({i, j})) {
        String key = "${i},${j}";
        if (!segments.containsKey(key)) {
          segments[key] = [];
        }

        final segList = segments[key]!;
        if (!segList.contains({i, j})) {
          segList.add({i, j});
        }

        visit(i, j);
      }
    }
  }

