          for (var dir in [-cols - 1, -cols, -cols + 1,
                           -1,           0,   +1,
                           +cols - 1, +cols, +cols + 1]) {
            var newIdx = indexes.last + dir;
            if (newIdx >= 0 && newIdx < rows * cols &&
                !seen.contains(newIdx) && 
                grid[newIdx % cols][newIdx ~/ cols] == word[i]) {
