          for (int j = len; j < word.length; ++j) {
            String current = indexToWordMap[indexes.last]![len];
            if (current[j] != word[j]) {
              current = current.replaceRange(len, j, word.sublist(len, j+1));
              if (current.length != j + 1) { // Prevent invalid lengths
                indexToWordMap[indexes.last] = [current];
              }
            }
            if (current.endsWith(word)) {
              indexToWordMap[indexes.last] = [current];
              break;
            }
          }
        }
      }

      for (var key in indexToWordMap.keys) {
        List<String> words = indexToWordMap[key]!;
