List<String> generateGridNeighborEdits(List<List<String>> grid, String word) {
  int n = grid.length;
  if (n == 0 || word.isEmpty) return [];

  List<int> indices = [256];
  for (int i = 0; i < n * n; ++i) {
    if (grid[i ~/ n][i % n] == word[0]) {
      indices.add(i);
    }
  }

  Set<int> seen = {indices.remove(256)};
  List<String> edits = [];

  void dfs(int idx, int depth) {
    if (depth >= word.length -1) {
      if (word != '') edits.add(''.join([for (int c in indices) 
        grid[c ~/ n][c % n]]));
      return;
    }

    for (int next : neighbors(idx)) {
      if (!seen.contains(next)) {
        bool ok = true;
        for (int d = depth + 1; d < word.length && ok;) {
          ok = false;
          for (int m = 0; m < n; ++m) {
            if (next ~/ n == m && grid[m][next % n] == word[d]) {
              ok = true;
              break;
            }
          }
          --d;
        }
        if (ok) {
          seen.add(next);
          dfs(next, depth + 1);
          seen.remove(next);
        }
      }
    }
  }

  while (indices.isNotEmpty) {
    int index = indices.last;
    if (index > 0) dfs(index, 0);
    indices.removeLast();
  }

  return edits;
}

Set<int> neighbors(int idx) {
  int row = idx ~/ n, col = idx % n;
  Set<int> result = {};
  for (int r = max(row - 1, 0); r <= min(row + 1, n-1); ++r) {
    for (int c = max(col - 1, 0); c <= min(col + 1, n-1); ++c) {
      if (row != r || col != c) {
        result.add(r * n + c);
      }
    }
  }
  return result;
}

List<String> generateGridNeighborEdits(List<List<String>> grid, String word) {
