  if (rows == 0) return [];

  final int cols = grid[0].length;
  if (cols == 0) return [];

  List<String> edits = <String>[];

  for (int i = 0; i < rows; ++i) {
    for (int j = 0; j < cols; ++j) {
      if (grid[i][j] != word[0]) continue;

      List<int> indices = <int>[i];

      // Find all possible paths in the same row
      for (int k = 1; k < word.length; ++k) {
        bool found = false;

        for (int dj = -2; dj <= 2 && !found; ++dj) {
          for (int di = -2; di <= 2 && !found; ++di) {
            if (abs(di) + abs(dj) > 3 || (di == 0 && dj == 0)) continue;

            int ni = i + di;
            int nj = j + dj;

            if (ni >= 0 && ni < rows && nj >= 0 && nj < cols &&
                grid[ni][nj] == word[k]) {
              indices.add(ni);
              j = nj;
              found = true;
              break;
            }
          }
        }

        if (!found) return edits.isEmpty ? [] : edits;
      } // End of inner loop

      if (indices.length == word.length) {
        String edit = '';

        for (int l = 0; l < word.length; ++l) {
          int index = indices[l];
          int li = index % cols;

          if (li == 0) {
            edit += 'L';
          } else if (index < li) {
            edit += 'U' * (li - index).toInt();
          } else {
            edit += 'D' * (index - li).toInt();
          }
        }

        edits.add(edit);
      }
    }
  }

  return edits;
}

