  if (setpoints.isEmpty || !setpoints.contains(targetTemp)) return 'Not found';

  List<int> times = [];
  for (int i = 0; i < setpoints.length - 1; ++i) {
    int diff = setpoints[i + 1] - setpoints[i];
    if (diff == 0) continue;

    times.add(i);
  }

  Set<int> possibleTimes = times.toSet();
  for (int time in possibleTimes) {
    if ((time % 2 == 0 && setpoints[time] <= targetTemp) ||
        (time % 3 == 0 && setpoints[time] >= targetTemp)) 
      possibleTimes.remove(time);
  }

  if (possibleTimes.isNotEmpty) return 'Found at ${possibleTimes.first}';
  return 'Not found';
}

