        buckets[bucketIndex] = value;
        index = bucketIndex;
      } else {
        buckets[bucketIndex] = '';
        index = bucketIndex;
      }
    } else if (opStr.startsWith('h')) {
      var parts = opStr.split(':');
      var key = parts[1];

