        var newContent = buckets[nextHash];
        buckets[nextHash] = currentContent;
        currentContent = newContent;
      }

      buckets[b] = currentContent;
      index = b;
    } else {
      print('invalid operation: $opStr');
    }
  }

  List<String> result = [];
  for (int i = 0; i < numBuckets; ++i)
    result.add(buckets[i]);

