bool validateBarcodeStrips(List<int> digits, List<String> bracketTypes) {
  if (digits.length != bracketTypes.length || digits.isEmpty) return false;

  int total = 0;
  for (int i = 0; i < digits.length; ++i) {
    final digit = digits[i];
    final type = bracketTypes[i];

    switch (type) {
      case "L":
        // Left brackets must be even
        if (digit % 2 == 1) return false;

        // Check that the next character is an R or C
        if ((i + 1) >= digits.length ||
            !{'R', 'C'}.contains(bracketTypes[i+1])) return false;

        break;

      case "R":
        // Right brackets can be any parity

        // Check that previous was L or N
        if ((i - 1) < 0 || !(bracketTypes[i-1] == 'L' || bracketTypes[i-1] == 'N')) 
          return false;

        // Check that current and next are not both R
        if (i < digits.length - 1 && bracketTypes[i+1] == 'R') return false;

        break;

      case "C":
        // Center brackets must have even count of digits between them?
        // Wait, no. The center brackets require two adjacent R's.
        // So check that there exists at least one pair of adjacent R's in a row.

        bool hasDoubleR = false;
        for (var j in [i - 1, i]) {
          if (j >= 0 && bracketTypes[j] == 'R') {
            if (!hasDoubleR) {
              hasDoubleR = true;
              continue;
            }
            return false;
          } else if (j < digits.length - 1) {
            if (bracketTypes[j + 1] == 'R') {
              if (!hasDoubleR) {
                hasDoubleR = true;
                continue;
              }
              return false;
            }
          }
        }

        if (!hasDoubleR) return false;
        break;
    }

    total += digit;
  }

  // Total must be divisible by 3 to pass checksum
  return total % 3 == 0;
}

