    var leftBracketType = bracketTypes[i];
    var rightBracketType = bracketTypes[i+1];

    if (leftBracketType == rightBracketType) continue;
    else if (leftBracketType == "B" && rightBracketType == "C") {
      pattern.add("A");
    } else if (leftBracketType == "C" && rightBracketType == "B") {
      pattern.add("B");
