  bool? lastValidDigit = true;

  void checkBrackets(int index, String type) {
    if (index >= digits.length) {
      if (currentPatternIndex != null &&
          currentPatternIndex! < pattern.length) {
        if ((type == "B" && pattern[currentPatternIndex!] == "B")) {
          currentPatternIndex++;
        } else if (type == "A") {
          currentPatternIndex = null;
        }
      }
    } else if (lastValidDigit != null) {
      if (type == "B" && lastValidDigit!) {
        // B is black
      } else if (type == "W" && !lastValidDigit!) {
        // W is white
      } else {
        return false;
      }

      if (pattern.contains(type)) {
        if (currentPatternIndex != null) {
          if (currentPatternIndex! < pattern.length && pattern[currentPatternIndex!] == type) {
            currentPatternIndex++;
          } else {
            return false;
          }
        } else {
          currentPatternIndex = 0;
        }
      } else {
        return false;
      }
    }
  }

  for (var digit in digits) {
    if (digit % 2 == 0) {
      checkBrackets(digit ~/ 2, "W"); // even => white
    } else {
      checkBrackets(digit ~/ 2 + 1, "B"); // odd => black
    }
  }

  return currentPatternIndex == null ||
         currentPatternIndex! < pattern.length && pattern[currentPatternIndex!] == "A";
}

