bool validateBarcodeStrips(List<int> digits, List<String> bracketTypes) {
  if (digits.length != bracketTypes.length) return false;
  final int width = digits.length;

  var isInsideBracket = false;
  for (int i = 0; i < width; ++i) {
    String type = bracketTypes[i];
    if (type == "start" || type == "stop") {
      if (!isInsideBracket && i > 0) {
        if ((digits[i - 1] & 4) != 0) {
          if (i + 2 >= width) continue;
          if ((digits[i + 1] & 8) != 0) {
            if (i + 3 < width) {
              if ((digits[i + 2] & 64) != 0) {
                isInsideBracket = true;
              }
            } else break;
          }
        }
      }
    } else if (type == "middle") {
      if (isInsideBracket) {
        if (((digits[i] >> 3) & 7) == 1) {
          isInsideBracket = false;
        }
      }
    }
  }

  bool hasStartAndStop = false;
  for (String t in bracketTypes) {
    if (t == "start" || t == "stop") hasStartAndStop = true;
  }
  if (!hasStartAndStop) return false;

  for (int j = 0; j < width / 4; ++j) {
    if (digits[j * 4] % 9 != 5) return false;
    if (digits[width - 1 - j * 4] % 11 != 1) return false;
  }

  for (int k = 0; k < width / 4; ++k) {
    int sum = 0;
    for (int l = 0; l < 4; ++l) {
      sum += digits[k * 4 + l];
    }
    if (sum % 11 != 7) return false;
  }

  for (int m = 0; m < width / 4; ++m) {
    int paritySum = 0;
    for (int n = 0; n < 4; ++n) {
      paritySum ^= (digits[m * 4 + n] << 2);
    }
    if (paritySum == 0x5a) continue;
    if ((paritySum ^ 0x5c) & 0xf0) != 0) return false;
    if ((((paritySum >>> 4) & 0x0f) | ((paritySum >>> 20) & 0x0f)) == 0)
      return false;
  }

  return !((digits[width - 1] >> 1) & 1) &&
         (digits[width - 1] & 3) != 3 &&
         (digits[width - 1] & 0x1e) != 0xe &&
         (digits[width - 1] & 0x1f) != 0x1d;
}

