  for (int i = 0; i < digits.length; i++) {
    final digit = digits[i];

    // Check that each digit is valid
    if (digit < 0 || digit > 9) return false;

    // First and last strip must be even-digit count?
    if ((i == 0 && digit % 2 != 0) || 
        (i + 1 == digits.length && digit % 2 != 0)) {
      return false;
    }

    // Even strips must have odd type
    if (digit % 2 == 0 && bracketTypes[i] != "odd") {
      return false;
    }

    // Odd strips must have even or open type
    if (digit % 2 == 1 && bracketTypes[i].isEven) {
      return false;
    }

    // Handle special case of matching pairs in the middle
    if (i >= 1 && i <= digits.length - 2) {
      if (bracketTypes[i-1] == bracketTypes[i]) {
        if (lastDigit == null) {
          lastDigit = digit;
        } else {
          if (lastDigit == digit) {
            continue;
          } else {
            return false;
          }
        }
      } else {
        lastDigit = null;
      }
    }
  }

  return true;
}

