      case 'T': ++t;
      break;
      case 'C': ++c;
      break;
      case 'G': ++g;
      break;
    }
  }

  double length = dna.length.toDouble();
  var counts = [a / length * 100.0, t / length * 100.0,
               c / length * 100.0, g / length * 100.0];

  List<String> parts = [];
  for (var count in counts) {
    int rounded = ((count + .5).round());
    parts.add('$rounded%');
  }

  return 'A: ${parts[0]}, T: ${parts[1]}, C: ${parts[2]}, G: ${parts[3]}';
}

String dnaComposition(String dna) {
  if (dna == '') return '';

  final nucleotides = ['A', 'T', 'C', 'G'];
  int count;
  String mostCommon = '';
  for (final n in nucleotides) {
    count = 0;
    for (int i=0; i < dna.length; ++i) {
      if (dna[i] == n) {
        count++;
      }
    }

    if (count > count || n.compareTo(mostCommon) < 0) {
      mostCommon = n;
      count = count;
    }
  }

  return '$mostCommon $count';
}

String dnaComposition(String dna) {
  if (dna.isEmpty || !RegExp(r'^[ACGT]+$').hasMatch(dna)) return '';

  final counts = <String, int>{};
  for (var base in dna.split('')) {
    counts.putIfAbsent(base, () => 0)++;
  }

  String result;
  var first = true;

  void add(char, count) {
    if (!first) result += ', ';
    result += '$char: $count';
    first = false;
  }

  counts.forEach(add);
  return result;
}

