  List<int> prefixSums = [0];
  for (int i=0; i < n-1; i++) {
    prefixSums.add(prefixSums[i] + quantities[i].toInt());
  }
  prefixSums.add(quantities[n-1]);

  Set<List<int>> uniquePrefixes = {prefixSums};

  Map<int, List<bool>> validStarts = {};

  void dfs(int idx, List<int> current) {
    if (idx >= n) return;

    current.add(idx);
    int sum = current.fold(0, (a,b) => a + b);
    if (sum > maxSum.toInt()) return;

    validStarts.putIfAbsent(current[0], () => []).add(true);

    dfs(idx+1, current); 
    current.removeLast();
  }

  dfs(0, []);

  List<int> candidates = [...validStarts.keys];
  candidates.sort((a, b) => validStarts[a]!.length - validStarts[b]!);

  List<String> result = [];

  for (int start in candidates) {
    if (start >= n) continue;
    if (!uniquePrefixes.contains(start)) continue;

    List<int> window = prefixSums.sublist(start).takeWhile((v) => v <= maxSum.toInt()).toList();
    if (window.isEmpty) break;

    bool possible = true;
    while (possible && window.isNotEmpty) {
      int last = window.last;
      for (int j=start; j < n; j++) {
        if (j != start) {
          int newTotal = j <= last ? window[j - start] : 0;
          if (newTotal == 0) break;

          List<int> updated = [
            ...window.take(j - start),
            newTotal
          ];
