    if (visited.contains(cell)) return;

    // Compute manhattan distance to target
    final distToTarget = abs(row - targetRow) + abs(col - targetCol);
    final score = ((stepsFromStart * 10.0) / (distToTarget == 0 ? 1 : distToTarget));

