        case 'right':
          if (col < cells[row].length-1 && !cells[row][col+1].contains('W')) dfs(cells[row][col+1], row, col+1, stepsFromStart+1); break;
        case 'down': 
          if (row < cells.length-1 && !cells[row+1][col].contains('W')) dfs(cells[row+1][col], row+1, col, stepsFromStart+1); break;
        case 'left':
          if (col > 0 && !cells[row][col-1].contains('W')) dfs(cells[row][col-1], row, col-1, stepsFromStart+1); break;
