List<String> sortMazeCellsByPriority(List<String> cells, int targetRow, int targetCol) {
  List<Set<int>> paths = [];
  for (String cell in cells) {
    if (cell == '') continue;
    Set<int> path = {};
    int row = int.parse(cell[0]);
    int col = int.parse(cell[1]);
    Queue<List<int>> queue = [row, col];
    bool found = false;
    while (!found && queue.isNotEmpty) {
      int r = queue.removeAt(0);
      int c = queue.removeAt(0);
      if (r == targetRow && c == targetCol) {
        found = true;
        break;
      }
      if (c > 0) queue.add([r, c - 1]);
      if (c < (cells.length / rows)) queue.add([r, c + 1]);
      if (r > 0) queue.add([r - 1, c]);
      if (r < (rows - 1)) queue.add([r + 1, c]);
    }
    if (found) path.addAll(queue.map((e) => e));
    else path.clear();
    paths.add(path);
  }

  List<String> sortedCells = [...cells];
  sortedCells.sort((a, b) {
    int aIndex = cells.indexOf(a);
    int bIndex = cells.indexOf(b);
    return paths[aIndex].length.compareTo(paths[bIndex].length);
  });

  return sortedCells;
}

