  var distA = manhattanDistance(cellA.row, cellA.col, targetRow, targetCol);
  var distB = manhattanDistance(cellB.row, cellB.col, targetRow, targetCol);

  if (distA != distB) {
    return distA - distB;
  }

  // Second priority: row number ascending
  if (cellA.row != cellB.row) {
    return cellA.row.compareTo(cellB.row);
