bool canReachTargetSignal(List<int> bins, int target) {
  // A router samples wifi signal strength into bins. To avoid interference,
  // chosen bins must be non-adjacent. Decide whether some selection of
  // non-adjacent bins sums exactly to the target combined strength.
  if (target < 0) return false;
  // notTaken[s]: sum s reachable with the previous bin NOT selected.
  // taken[s]: sum s reachable with the previous bin selected.
  List<bool> notTaken = List<bool>.filled(target + 1, false);
  List<bool> taken = List<bool>.filled(target + 1, false);
  notTaken[0] = true;
  for (int i = 0; i < bins.length; i++) {
    final int b = bins[i];
    final List<bool> newTaken = List<bool>.filled(target + 1, false);
    final List<bool> newNot = List<bool>.filled(target + 1, false);
