Map<String, int> resolveTimetableLog(List<String> log) {
  // Schedule is a stack of departure minutes. Supported log entries:
  //   'ADD <m>'  push departure minute m
  //   'CANCEL'   remove the most recently scheduled departure
  //   'UNDO'     revert the most recent effective ADD or CANCEL
  // Unrecognized entries, CANCEL on an empty schedule, and UNDO with
  // nothing to undo are counted as ignored.
  final schedule = <int>[];
  final history = <List<int>>[]; // [0, m] = ADD m, [1, m] = CANCEL removed m
  var ignored = 0;
  for (final entry in log) {
    if (entry.startsWith('ADD ')) {
      final m = int.parse(entry.substring(4));
      schedule.add(m);
      history.add([0, m]);
    } else if (entry == 'CANCEL') {
      if (schedule.isEmpty) {
        ignored++;
      } else {
        final m = schedule.removeLast();
        history.add([1, m]);
      }
    } else if (entry == 'UNDO') {
      if (history.isEmpty) {
        ignored++;
      } else {
        final op = history.removeLast();
        if (op[0] == 0) {
          schedule.removeLast();
        } else {
          schedule.add(op[1]);
        }
      }
    } else {
      ignored++;
    }
  }
  var sum = 0;
  var minVal = -1;
  var maxVal = -1;
  for (final m in schedule) {
    sum += m;
    if (minVal == -1 || m < minVal) minVal = m;
    if (maxVal == -1 || m > maxVal) maxVal = m;
  }
  return {
    'count': schedule.length,
    'sum': sum,
    'min': minVal,
    'max': maxVal,
    'ignored': ignored,
  };
}

