bool canTransmitExactly(List<int> packets, int budget) {
  // Decide whether some selection of packets can fill the transmission
  // budget exactly. Each packet may be:
  //   - skipped entirely,
  //   - sent whole, or
  //   - fragmented once into a half-size piece (only if its size is even),
  //     in which case only one half is sent in this window.
  bool helper(int index, int remaining) {
    if (remaining == 0) {
      return true;
    }
    if (remaining < 0 || index >= packets.length) {
      return false;
    }
    // Option 1: skip this packet.
    if (helper(index + 1, remaining)) {
      return true;
    }
    // Option 2: send the whole packet.
    if (helper(index + 1, remaining - packets[index])) {
      return true;
    }
    // Option 3: send one half of an even-sized packet.
    if (packets[index] % 2 == 0 &&
        helper(index + 1, remaining - packets[index] ~/ 2)) {
      return true;
    }
    return false;
  }

  return helper(0, budget);
}

