List<int> resolveBucketLoads(List<int> hashes, int maxLoad) {
  // Fold each hash to 16 bits (xor high half into low half), then place
  // items into a power-of-two bucket table using index = h & (n - 1).
  // Starting from n = 1, keep doubling the table while some bucket holds
  // more than maxLoad items AND that bucket contains at least two distinct
  // folded hashes (duplicates can never be separated, so splitting for
  // them is pointless). Returns the bucket load counts of the final table.
  final cap = maxLoad < 1 ? 1 : maxLoad;
  final folded = <int>[];
  for (final h in hashes) {
    folded.add((h ^ (h >>> 16)) & 0xFFFF);
  }
  var n = 1;
  while (true) {
    final counts = List<int>.filled(n, 0);
    final distinct = List<Set<int>>.generate(n, (_) => <int>{});
    final mask = n - 1;
    for (final h in folded) {
      final idx = h & mask;
      counts[idx]++;
      distinct[idx].add(h);
    }
    var needSplit = false;
    for (var i = 0; i < n; i++) {
      if (counts[i] > cap && distinct[i].length > 1) {
        needSplit = true;
        break;
      }
    }
    if (!needSplit || n >= 1 << 16) {
      return counts;
    }
    n <<= 1;
  }
}

