void normalizeAndTrim(List<double> list, int percent) {
  list.sort((a,b) => a.compareTo(b));
  int cutOffIndex = (list.length * percent).roundToDouble().toInt();
  if (cutOffIndex >= list.length || cutOffIndex <= 0) {
    list.clear(); 
  } else {
    list.removeRange(0, list.length - cutOffIndex);
  }
}

List<double> findClusters(List<double> data, int windowSize) {
  List<double> peaks = [];

  int prevDiff = 0;
  int upCount = 0;
  bool isUpwardTrend = false;

  for (int i = 0; i < data.length && !isUpwardTrend; ++i) {
    var diff = data[i] > data[i-1];
    if (!prevDiff || diff != prevDiff) {
      if (diff) upCount++;
      prevDiff = diff ? 1 : 0;
    }
    if (upCount >= 2) isUpwardTrend = true;
  }

  for (int i = 0; i < data.length - windowSize; ++i) {
    var current = data[i]; 
    var start = i;
    while (start < i + windowSize && start < data.length && data[start] < current) {
      start++;
    }
    if (start == i + windowSize) continue;
    var end = i + windowSize;
    while (end < data.length && data[end] < current) {
      end++;
    }
    if ((start < end) && (end > i)) {
