String orderedServerLogs(List<String> logs) {
  List<int> timestamps = [];
  for (int i = 0; i < logs.length; ++i) {
    String log = logs[i];
    int timestamp = 0;
    int j = 0, k = 0;
    while (j < log.length && '0' <= log[j] && log[j] <= '9') {
      timestamp *= 10;
      timestamp += log[j].codeUnitAt(0) - '0'.codeUnitAt(0);
      ++j;
    }
    if (log[0] == '[') {
      j++;
    } else {
      j = 2;
    }
    while (k < log.length - j && log[k + j] != ')') {
      ++k;
    }
    if (k > 0) {
      ++timestamp;
    }
    timestamps.add(timestamp);
  }

  List<int> indices = [for (int i = 0; i < logs.length; ++i) i];

  void merge(int left, int mid, int right) {
    int n1 = mid - left + 1;
    int n2 = right - mid;

    List<int> L = List.filled(n1, 0);
    List<int> R = List.filled(n2, 0);

    for (int i = 0; i < n1; ++i)
      L[i] = indices[left + i];
    for (int j = 0; j < n2; ++j)
      R[j] = indices[mid + 1 + j];

    int i = 0, j = 0;
    int k = left;

    while (i < n1 && j < n2) {
      if (timestamps[L[i]] <= timestamps[R[j]]) {
        indices[k++] = L[i++];
      } else {
        indices[k++] = R[j++];
      }
    }

    while (i < n1) {
      indices[k++] = L[i++];
    }

    while (j < n2) {
      indices[k++] = R[j++];
    }
  }

  void mergeSort(int l, int r) {
    if (l < r) {
      int m = (l + r) ~/ 2;
      mergeSort(l, m);
      mergeSort(m + 1, r);
      merge(l, m, r);
    }
  }

  mergeSort(0, logs.length - 1);

  List<String> result = [];

  for (int i = 0; i < indices.length; ++i) {
    result.add(logs[indices[i]]);
  }

  return result.join('\n');
}

