String thermostatScheduleDrift(List<int> dailyMasks, int referenceMask) {
  if (dailyMasks.length == 0 || referenceMask < 0 || referenceMask > 15) return 'Invalid';

  final shifts = [86400 * i for i in 0..(referenceMask - 1)];
  var drifts = List<int>.filled(dailyMasks.length, 0);

  for (var shiftIndex = 0; shiftIndex <= referenceMask; ++shiftIndex) {
    for (var dayIndex = 0; dayIndex < dailyMasks.length; ++dayIndex) {
      int mask = dailyMasks[dayIndex];

      while ((mask & (1 << shiftIndex)) != 0 && shiftIndex < referenceMask) {
