    double deviationPercentage = drifts[index].toDouble() / totalShifts.toDouble(); 
    result += '$deviationPercentage% ';
  }

  return result.trim();
}

double findMedian(List<int> list) {
  List<int> sortedList = [...list];
  sortedList.sort((a, b) => a.compareTo(b));
  int mid = sortedList.length ~/ 2;
  return sortedList.length.isEven ? (sortedList[mid - 1] + sortedList[mid]) / 2 : sortedList[mid];
}

double computeStandardDeviation(List<int> data) {
  if (data.isEmpty) return 0.0;
  double mean = data.reduce((a, b) => a + b) / data.length;
  double variance = data.map((x) => pow(x - mean, 2)).reduce((a, b) => a + b) / data.length;
  return sqrt(variance);
}

