    var currentRow = samples[i];

    for (var j = 0; j < currentRow.length - 1; ++j) {
      if (abs(currentRow[j] - samples[i-1][j]) > maxJump) {
        // Check the next row to see if it can be aligned
        while (i + 1 < rows && abs(samples[i+1][j] - samples[i][j]) <= maxJump) {
