        if (i == rows - 1) break;

        // If no more rows left and we're still not aligned, skip this column
        if (currentRow[j] != samples[i][j]) continue;
      } else {
        // Ensure that all previous values are stable within maxJump from last valid one
        bool isAligned = false;
        int prevValue = samples[i-1][j];
        for (int k = i - 2; k >= 0; --k) {
          if (abs(samples[k][j] - prevValue) <= maxJump) {
