      // Align with the last known value in this column across all rows
      if (i == rows - 1 || !isAligned) {
        for (int k = i + 1; k < rows; ++k) {
          if (abs(samples[k][j] - samples[i][j]) <= maxJump) {
            if (i == rows - 1) {
