    } else if (action == "discard") {
      if (val <= 0 || val > playerCount) return false;
      hasDiscard = true;
    } else if (action == "roll") {
      if (val < 1 || val > 6) return false;
    }
  }

  if (!hasDiscard) return false;

  if (keptValues.isNotEmpty && keptValues.any((v) => v > playerCount)) return false;

  Set<int> allPlayersUsed = {};
  for (final event in events.skip(1).whereType<String>()) {
    if (event.contains("player")) {
