        if (low == -1 || chargeLevels[i] < chargeLevels[low])
          low = i;
        else if (i != low)
          break;
      } else {
        if (high == -1 || chargeLevels[i] > chargeLevels[high])
          high = i;
        else if (i != high)
          break;
      }
    }
    if (low == -1 || high == -1) return states;
    if (low == high) continue;
    List<int> left = chargeLevels.sublist(0, low + 1);
    List<int> right = chargeLevels.sublist(high, chargeLevels.length);
    bool stable = true;
    for (int j = 0; j < min(left.length, right.length); j++)
      if (left[j] != right[right.length - 1 - j]) {
        stable = false;
        break;
      }
    if (stable) {
      states.add('flat');
      chargeLevels = [...chargeLevels.sublist(low + 1), ...right];
    } else {
      states.add('peak');
      chargeLevels.removeAt(low);
    }
  }
  if (chargeLevels.isEmpty) return states;
  List<int> finalCharge = [chargeLevels[0]];
  for (int i = 1; i < chargeLevels.length; i++) {
    if (finalCharge.last != chargeLevels[i]) finalCharge.add(chargeLevels[i]);
