  if (states.contains('flat') && !finalCharge.contains(finalCharge.first))
    states.insert(states.indexOf('flat'), 'discharged');
  else if (finalCharge.length <= 3 &&
      finalCharge.every((x) => x == finalCharge[0])) {
    states.add('flat');
  }
  if (states.isEmpty) states.add('unknown');
  return states;
